import os
import torch


class Config:
    # ==== System & Reproducibility ====
    seed = 42
    num_workers = 4
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # ==== File Paths ====
    # Input data (Read-Only)
    input_dir = "./input"

    # Metadata (Generated by previous steps)
    metadata_dir = "./metadata"
    train_path = os.path.join(metadata_dir, "train.csv")
    val_path = os.path.join(metadata_dir, "val.csv")
    test_path = os.path.join(metadata_dir, "test.csv")

    # Working Directory (For caching and checkpoints)
    # Using 'idea_12' as specified for this experiment iteration
    working_dir = "./working/idea_12"
    output_dir = working_dir  # Alias

    # Submission
    submission_dir = "./submission"
    submission_path = os.path.join(submission_dir, "submission.csv")

    # ==== Model Architecture ====
    model_name = "microsoft/deberta-v3-base"
    max_length = 512  # Max sequence length for tokenization
    hidden_dropout_prob = 0.1
    attention_probs_dropout_prob = 0.1

    # ==== Data Processing ====
    # If True, use a small subset of data for debugging
    debug = False
    debug_sample_size = 100

    # Symmetric Augmentation: Double train data by swapping (A, B) -> (B, A)
    use_symmetric_augmentation = True

    # Test Time Augmentation: Predict on (A, B) and (B, A) and average
    use_tta = True

    # ==== Training Hyperparameters ====
    epochs = 3
    train_batch_size = (
        8  # Adjust based on VRAM (A100 40GB can likely handle 8-16 with 512 seq len)
    )
    valid_batch_size = 16

    # Gradient Accumulation to simulate larger batch sizes
    gradient_accumulation_steps = 2

    # Optimizer settings
    learning_rate = 1e-5
    weight_decay = 0.01
    warmup_ratio = 0.1
    max_grad_norm = 1.0

    # Mixed Precision
    fp16 = True

    # Early Stopping
    patience = 3  # Number of checks with no improvement

    def __init__(self):
        # Ensure working directories exist
        os.makedirs(self.working_dir, exist_ok=True)
        os.makedirs(self.submission_dir, exist_ok=True)

    def get_model_save_path(self):
        return os.path.join(self.working_dir, "best_model.pth")

    def get_cache_path(self, dataset_name):
        """
        Returns the path for cached processed data (parquet format).
        dataset_name: 'train', 'val', or 'test'
        """
        return os.path.join(self.working_dir, f"{dataset_name}_data.parquet")
